Changes:

cli/src/worktrunk/core.ts
  @@ -468,7 +468,7 @@ export function removeOne(ctx: WorktreeContext, token: string, options: RemoveOp
  -        if (hidden) throw new WorktreeError(`${hidden}; restore or commit it, or pass --force`);
  +        if (hidden) throw new WorktreeError(`${hidden}; clear the flag (\`git update-index --no-assume-unchanged --no-skip-worktree <file>\`) or restore the file, or pass --force`);
         }
         removeSeams.beforeRemove?.(entry);
         // A commit made here since the integration check (another session's `/commit`, an editor) must not be lost with
  +1 -1

cli/src/worktrunk/verification.ts
  @@ -39,9 +39,11 @@ function filesystemCapabilities(gitDir: string): { modes: boolean; symlinks: boo
  -      fs.writeFileSync(file, "x");
  +      fs.writeFileSync(file, "x", { mode: 0o644 });
  +      fs.chmodSync(file, 0o644);
  +      const plain = (fs.statSync(file).mode & 0o111) === 0; // a filesystem that fakes modes shows every file executable
         fs.chmodSync(file, 0o755);
  -      modes = (fs.statSync(file).mode & 0o111) !== 0;
  +      modes = plain && (fs.statSync(file).mode & 0o111) !== 0; // and one that ignores chmod never shows the bit appear
       } catch { /* no exec bits */ }
       try { fs.symlinkSync("f", path.join(probe, "l")); symlinks = true; } catch { /* no symlinks */ }
       return { modes, symlinks };
  +4 -2

cli/test/worktrunk_hidden.test.ts
  @@ -67,19 +67,23 @@ for (const hider of HIDERS) {
  +      assert.match(r.output, /hides|hidden/, "refused by the hidden-edit check, not by the waiver parsing");
         assert.ok(fs.existsSync(f.dir));
       } finally { f.cleanup(); }
     });

  -  test(`remove keeps a worktree holding a hidden edit (${hider.name}) unless forced`, () => {
  +  test(`remove refuses a worktree holding a hidden edit (${hider.name}) unless forced`, () => {
       const f = fixture("feat/remove");
       try {
         git(f.repo, "merge", "--ff-only", "-q", "feat/remove"); // integrated: the only thing left to lose is the hidden edit
         hider.hide(f.dir);
         const r = f.run(f.repo, ["remove", "feat/remove"]);
         assert.equal(r.success, false, r.output);
  +      assert.match(r.output, /hides|hidden/);
         assert.ok(fs.existsSync(f.dir), "the worktree survives");
  -      if (hider.name.startsWith("assume")) assert.equal(fs.readFileSync(path.join(f.dir, "a.txt"), "utf8"), "hidden edit\n", "and so does the edit");
  +      const forced = f.run(f.repo, ["remove", "feat/remove", "--force"]);
  +      assert.equal(forced.success, true, `--force discards knowingly: ${forced.output}`);
  +      assert.equal(fs.existsSync(f.dir), false);
       } finally { f.cleanup(); }
     });

  @@ -90,7 +94,7 @@ for (const hider of HIDERS) {
  -      assert.match(r.output, /kept 1|hides/);
  +      assert.match(r.output, /kept .*hides/, "kept for that reason");
       } finally { f.cleanup(); }
     });
   }
  +7 -3
