  1 │ /**
  2 │  * Verification records for named-worktree merges.
  3 │  *
  4 │  * A CLI merge has no in-memory agent receipt, so the agent run (or any verifier Nexus ran and saw pass) records
  5 │  * `branch + head + tree` in the registry. The tree is that of the working state at the time (HEAD plus uncommitted
  6 │  * work, as `git add -A` would commit it), so a later edit or commit no longer matches. Running a project verifier is
  7 │  * not done here: that stays under the approval model of WP-1313.
  8 │  */
  9 │ import * as fs from "node:fs";
 10 │ import * as os from "node:os";
 11 │ import * as path from "node:path";
 12 │ import { redactSecrets } from "../ui.js";
 13 │ import { statusOf } from "./core.js";
 14 │ import { git, gitOut, nestedRepositoryReason, parseSubmoduleStatus } from "./git.js";
 15 │ import { MAX_BRANCH_LENGTH, MAX_RECORDS, updateRegistry, type Registry } from "./registry.js";
 16 │ import { currentEntry, openRepo } from "./repo.js";
 17 │ 
 18 │ /** Pathspec of `.nexus/` (sessions, knowledge, worktrees): unstaged after `add -A` so it never reaches a backup, a receipt or an automatic commit. */
 19 │ export const NEXUS_STATE_PATH = ":(top).nexus";
 20 │ 
 21 │ export interface WorkingState { head: string; tree: string; dirty: boolean }
 22 │ 
 23 │ /**
 24 │  * Configuration and index flags that make Git skip or misread a modification, overridden for the strict snapshot:
 25 │  * stat caching (`core.ignoreStat`), the executable bit (`core.fileMode`), symlinks, sparse checkout and the untracked
 26 │  * cache. Content conversion (`core.autocrlf`, filters, `.gitattributes`) is left alone: a merge's own `git add -A`
 27 │  * applies it too, so both sides agree on what the bytes become.
 28 │  */
 29 │ const STRICT_CONFIG = [
 30 │   "-c", "core.ignoreStat=false", "-c", "core.sparseCheckout=false", "-c", "core.sparseCheckoutCone=false",
 31 │   "-c", "core.untrackedCache=false", "-c", "core.splitIndex=false", "-c", "status.showUntrackedFiles=all",
 32 │ ];
 33 │ 
 34 │ /** Whether the filesystem under `gitDir` stores executable bits and symlinks; where it does not, Git sets `core.fileMode`/`core.symlinks` false for a reason and forcing them would turn every file into a change. */
 35 │ function filesystemCapabilities(gitDir: string): { modes: boolean; symlinks: boolean } {
 36 │   const probe = fs.mkdtempSync(path.join(gitDir, "nexus-probe-"));
 37 │   try {
 38 │     let modes = false;
 39 │     let symlinks = false;
 40 │     try {
 41 │       const file = path.join(probe, "f");
 42 │       fs.writeFileSync(file, "x", { mode: 0o644 });
 43 │       fs.chmodSync(file, 0o644);
 44 │       const plain = (fs.statSync(file).mode & 0o111) === 0; // a filesystem that fakes modes shows every file executable
 45 │       fs.chmodSync(file, 0o755);
 46 │       modes = plain && (fs.statSync(file).mode & 0o111) !== 0; // and one that ignores chmod never shows the bit appear
 47 │     } catch { /* no exec bits */ }
 48 │     try { fs.symlinkSync("f", path.join(probe, "l")); symlinks = true; } catch { /* no symlinks */ }
 49 │     return { modes, symlinks };
 50 │   } finally {
 51 │     fs.rmSync(probe, { recursive: true, force: true });
 52 │   }
 53 │ }
 54 │ 
 55 │ /**
 56 │  * The tree `git add -A` would commit (minus `.nexus`), via a temporary index. `fresh`: the index starts as
 57 │  * `read-tree HEAD` with the strict configuration, so nothing the repository's index or configuration says (an
 58 │  * `--assume-unchanged` or `--skip-worktree` flag, a stale stat entry, `core.fileMode=false`, a sparse checkout) can
 59 │  * hide an edit: every file is compared with HEAD by content and mode. Otherwise the user's own index is the start,
 60 │  * which is what a merge's `add -A` uses.
 61 │  */
 62 │ function snapshotTree(dir: string, fresh: boolean): string {
 63 │   const scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-tree-"));
 64 │   try {
 65 │     const env = { GIT_INDEX_FILE: path.join(scratch, "index") };
 66 │     const gitDir = gitOut(dir, ["rev-parse", "--path-format=absolute", "--git-dir"]);
 67 │     const realIndex = path.join(gitDir, "index");
 68 │     const config = [...(fresh ? STRICT_CONFIG : [])];
 69 │     if (fresh) {
 70 │       const capabilities = filesystemCapabilities(gitDir);
 71 │       if (capabilities.modes) config.push("-c", "core.fileMode=true");
 72 │       if (capabilities.symlinks) config.push("-c", "core.symlinks=true");
 73 │     }
 74 │     if (!fresh && fs.existsSync(realIndex)) {
 75 │       fs.copyFileSync(realIndex, path.join(scratch, "index"));
 76 │     } else {
 77 │       git(dir, [...config, "read-tree", "HEAD"], { env });
 78 │     }
 79 │     if (fresh) carryIndexIntentions(dir, config, env);
 80 │     git(dir, [...config, "add", "-A"], { env });
 81 │     git(dir, ["reset", "-q", "HEAD", "--", NEXUS_STATE_PATH], { env, allowFailure: true }); // internal state is never part of a merge
 82 │     return gitOut(dir, ["write-tree"], { env });
 83 │   } finally {
 84 │     fs.rmSync(scratch, { recursive: true, force: true });
 85 │   }
 86 │ }
 87 │ 
 88 │ /**
 89 │  * What the repository's own index legitimately says and a merge's `add -A` honours, carried into the fresh index:
 90 │  * a skip-worktree entry that is simply not on disk (sparse checkout) is not a deletion, and a new file the operator
 91 │  * staged on purpose with `add -f` stays even though it is ignored. A skip-worktree file that IS on disk is not
 92 │  * carried: an edit to it must be seen.
 93 │  */
 94 │ function carryIndexIntentions(dir: string, config: string[], env: Record<string, string>): void {
 95 │   const absentSparse: string[] = [];
 96 │   for (const entry of gitOut(dir, ["ls-files", "-v", "-z"]).split("\0")) {
 97 │     if (!/^[Ss] /.test(entry)) continue;
 98 │     const file = entry.slice(2);
 99 │     try { fs.lstatSync(path.join(dir, file)); } catch { absentSparse.push(file); }
100 │   }
101 │   if (absentSparse.length > 0) {
102 │     git(dir, [...config, "update-index", "--skip-worktree", "-z", "--stdin"], { env, input: absentSparse.join("\0") + "\0" });
103 │   }
104 │   const staged = gitOut(dir, ["diff-index", "--cached", "--name-only", "--diff-filter=A", "-z", "HEAD"]).split("\0").filter(Boolean)
105 │     .filter((file) => { try { fs.lstatSync(path.join(dir, file)); return true; } catch { return false; } });
106 │   if (staged.length > 0) {
107 │     git(dir, [...config, "add", "-f", "--pathspec-from-file=-", "--pathspec-file-nul"], { env: { ...env, GIT_LITERAL_PATHSPECS: "1" }, input: staged.join("\0") + "\0" });
108 │   }
109 │ }
110 │ 
111 │ /** HEAD, and the tree of the working state: HEAD^{tree} when clean, else a snapshot via a temporary index. */
112 │ export function workingState(dir: string, dirty: boolean): WorkingState {
113 │   const head = gitOut(dir, ["rev-parse", "--verify", "HEAD"]);
114 │   if (!dirty) return { head, tree: gitOut(dir, ["rev-parse", "--verify", "HEAD^{tree}"]), dirty };
115 │   return { head, tree: snapshotTree(dir, false), dirty };
116 │ }
117 │ 
118 │ /**
119 │  * Whether any initialised submodule of `dir`, nested ones included, holds uncommitted content (changes or untracked
120 │  * files), judged by the strict snapshot. The tree of the working state records only the submodule's gitlink, so such
121 │  * content would be tested by a verifier yet never be part of what a receipt authorises and a merge carries.
122 │  */
123 │ export function hasDirtySubmodule(dir: string): boolean {
124 │   for (const { path: rel, initialised } of parseSubmoduleStatus(gitOut(dir, ["submodule", "status", "--recursive"]))) {
125 │     if (!initialised) continue; // no content to differ
126 │     const sub = path.join(dir, rel);
127 │     if (snapshotTree(sub, true) !== gitOut(sub, ["rev-parse", "--verify", "HEAD^{tree}"])) return true;
128 │   }
129 │   return false;
130 │ }
131 │ 
132 │ /**
133 │  * A modification the repository's own index or configuration hides from `status` and `add -A` (`--assume-unchanged`,
134 │  * `--skip-worktree`, `core.fileMode=false`, stat caching) shows up as a difference between the strict snapshot and the
135 │  * tree a merge would commit. Anything that deletes a worktree, or merges it, refuses while one exists: the edit would be
136 │  * in no commit and in no backup. Undefined when there is none.
137 │  */
138 │ export function hiddenModificationReason(dir: string): string | undefined {
139 │   const normal = workingState(dir, statusOf(dir).total > 0).tree;
140 │   if (snapshotTree(dir, true) === normal) return undefined;
141 │   return "it holds a modification that Git's index or configuration hides (an `--assume-unchanged` or `--skip-worktree` file, `core.fileMode=false`) and that no merge or backup would carry";
142 │ }
143 │ 
144 │ /**
145 │  * The working state of `dir` for a receipt, or undefined when it cannot be certified: a submodule holds uncommitted
146 │  * content, or the strict snapshot (see `snapshotTree`) differs from the state a merge would commit, meaning something
147 │  * in the repository's index or configuration hides an edit from `status` and `add -A`. Whatever a verifier saw, the
148 │  * receipt must cover exactly what a merge carries.
149 │  */
150 │ function certifiableState(dir: string): WorkingState | undefined {
151 │   if (nestedRepositoryReason(dir) !== undefined) return undefined; // before any Git runs inside a submodule below
152 │   if (hasDirtySubmodule(dir)) return undefined;
153 │   const state = workingState(dir, statusOf(dir).total > 0);
154 │   return snapshotTree(dir, true) === state.tree ? state : undefined;
155 │ }
156 │ 
157 │ /** The linked worktree containing `workspace` and its working state, or undefined (main checkout, detached, not a repository). Never throws. */
158 │ export function captureVerificationState(workspace: string): WorkingState | undefined {
159 │   try {
160 │     const entry = currentEntry(openRepo(workspace));
161 │     if (!entry || entry.isMain || !entry.branch) return undefined;
162 │     return certifiableState(entry.path);
163 │   } catch {
164 │     return undefined;
165 │   }
166 │ }
167 │ 
168 │ /**
169 │  * Records that `verifier` passed on the current state of the linked worktree containing `workspace`. With `expected`
170 │  * (the state captured before the verifier started) nothing is recorded if the working state is no longer that state:
171 │  * an edit made while the verifier ran was not tested. Never throws.
172 │  */
173 │ export function recordVerification(workspace: string, verifier: string, expected?: WorkingState): boolean {
174 │   try {
175 │     const repo = openRepo(workspace);
176 │     const entry = currentEntry(repo);
177 │     if (!entry || entry.isMain || !entry.branch || entry.branch.length > MAX_BRANCH_LENGTH) return false;
178 │     const state = certifiableState(entry.path);
179 │     if (!state) return false;
180 │     if (expected && (expected.head !== state.head || expected.tree !== state.tree)) return false;
181 │     const branch = entry.branch;
182 │     updateRegistry(repo.commonDir, (reg) => {
183 │       const list = (reg.verifications ?? []).filter((item) => !(item.branch === branch && item.tree === state.tree && item.head === state.head));
184 │       list.push({ branch, head: state.head, tree: state.tree, verifier: redactSecrets(verifier).slice(0, 200) || "verifier", recordedAt: new Date().toISOString() });
185 │       reg.verifications = list.slice(-MAX_RECORDS);
186 │     });
187 │     return true;
188 │   } catch {
189 │     return false;
190 │   }
191 │ }
192 │ 
193 │ export interface RecordRequest {
194 │   unrecordableWorktree: boolean;
195 │   dryRun: boolean;
196 │   verifierSucceeded: boolean;
197 │   hasExecuted: boolean;
198 │   deliverableBound: boolean;
199 │   /** The verifier is the configured authoritative one or an independent one (never a discovered generic command). */
200 │   verified: boolean;
201 │   verifier: string;
202 │   /** The working state captured before the verifier ran. */
203 │   before?: WorkingState;
204 │ }
205 │ 
206 │ /** The agent's recording step: a receipt only for a passing, deliverable-bound, configured-or-independent run on the state that was tested. */
207 │ export function recordVerificationIfEligible(workspace: string, request: RecordRequest): boolean {
208 │   if (request.unrecordableWorktree || request.dryRun || !request.verifierSucceeded || !request.hasExecuted || !request.deliverableBound || !request.verified) return false;
209 │   if (!request.before) return false;
210 │   return recordVerification(workspace, request.verifier, request.before);
211 │ }
212 │ 
213 │ /** Whether the registry holds a verification matching this exact state (head when clean, tree when dirty). */
214 │ export function hasVerification(registry: Registry, branch: string, state: WorkingState): boolean {
215 │   return (registry.verifications ?? []).some((item) => item.branch === branch && item.tree === state.tree && (state.dirty || item.head === state.head));
216 │ }

