export interface MergeContextInfo {
  repo: ReturnType<typeof openRepo>;
  source: WorktreeEntry & { branch: string };
  branch: string;
  targetName: string;
  targetEntry: WorktreeEntry;
  targetSha: string;
  state: ReturnType<typeof statusOf>;
  gateState: ReturnType<typeof workingState>;
  waiver?: string;
  mergeBase: string;
