/** Loads env files in precedence order; CLI flags are applied afterwards by buildConfig. */
export function loadEnvironment(): void {
  // The operator's own environment and home, before any file has written to process.env.
  const operatorEnvironment = credentialAuthorityRecorded ? undefined : { ...process.env };
  if (!credentialAuthorityRecorded && operatorEnvironment) {
    shellEnvironment = { ...operatorEnvironment };
  }
  const operatorHome = operatorConfigHome();
  // 1. Installation directory defaults
  loadDotenv({ path: installEnv, quiet: true });
  // 2. Global user config (~/.config/nexus/config.env)
  const globalConfig = path.join(operatorHome, ".config/nexus/config.env");
  userConfigFile = {};
  if (fs.existsSync(globalConfig)) {
    loadDotenv({ path: globalConfig, override: true, quiet: true });
    userConfigFile = parseDotenv(fs.readFileSync(globalConfig));
  }
  // config.env is applied with override, so a HOME= line would move os.homedir() for the rest of the run while state,
  // restore and credentials stay located by the operator home captured above. Refuse rather than split the authorities.
  if (path.resolve(process.env.HOME || os.homedir()) !== path.resolve(operatorHome)) {
    // Leave nothing half-applied: put the operator's HOME back before refusing.
    if (shellEnvironment.HOME === undefined) delete process.env.HOME; else process.env.HOME = shellEnvironment.HOME;
    throw new Error("config.env may not change HOME; use NEXUS_STATE_DIR to relocate task and session state, and restart Nexus from the home you want");
  }
  // Structured operator settings are separate from the legacy dotenv file. They are read only from the
  // operator's home; a project nexus.config.json is never trusted as operator policy.
  operatorJsonOperationPolicy = undefined;
  operatorJsonOperationPolicyError = undefined;
  try {
    operatorJsonOperationPolicy = readOperatorOperationPolicy(path.join(operatorHome, ".config/nexus/config.json"));
  } catch (error) {
    // Preserve the invalid policy for buildConfig to reject. Deferring only the throw lets `nexus doctor`
    // report a structured config.valid finding; no execution path may proceed with policy defaults instead.
    operatorJsonOperationPolicyError = error instanceof Error ? error : new Error("Unable to read operator config.json.");
  }
  // A provenance setting chosen in the operator's shell outranks config.env, which was applied with override above:
  // config.env NEXUS_VERIFY_ATTESTATION=0 must not defeat an explicit NEXUS_VERIFY_ATTESTATION=1 for this run.
  for (const key of SHELL_PRECEDENCE_KEYS) {
    const shellValue = shellEnvironment[key];
    if (shellValue !== undefined) process.env[key] = shellValue;
  }
  // Credential bindings are decided by the operator environment and config.env only (see setCredentialAuthority).
  if (operatorEnvironment) {
    setCredentialAuthority({ ...operatorEnvironment, ...userConfigFile }, operatorHome);
    credentialAuthorityRecorded = true;
  }
  // 3. Current working directory overrides (skipped when cwd is the install directory: that file is the
  //    shipped default already applied in step 1 and must not outrank the user's global config). A project .env
  //    belongs to the repository, not the operator: only per-project settings in PROJECT_ENV_KEYS are applied; the
  //    rest (TLS and proxy settings, credentials, HOME, the shell, timeouts, fallbacks, trust) is ignored and reported.
  const cwdEnv = path.resolve(process.cwd(), ".env");
  projectEnvSettings = {};
  projectEnvIgnored = [];
  if (cwdEnv !== installEnv && fs.existsSync(cwdEnv)) {
    let project: Record<string, string> = {};
    try {
      // The repository (a sandboxed agent's worktree, say) controls this file: never a blocking or unbounded read.
      // A link to a regular file is followed (a dotfile manager's layout); what it leads to must still be a small plain file.
      const text = readSmallFile(fs.realpathSync(cwdEnv), MAX_PROJECT_ENV_BYTES);
      if (text !== undefined) project = parseDotenv(Buffer.from(text));
      else warnOnce(`project .env ${cwdEnv} was not read (not a regular file, or larger than ${MAX_PROJECT_ENV_BYTES / 1024} KiB)`);
    } catch {
      warnOnce(`project .env ${cwdEnv} was not read (it could not be resolved or read)`);
    }
    for (const [key, value] of Object.entries(project)) {
      if (isProjectEnvKey(key)) projectEnvSettings[key] = value;
      else projectEnvIgnored.push(key);
    }
    if (projectEnvIgnored.length) {
